import React, { Component } from 'react';
import { Card, Table, Icon, Button, Spin, Alert, Input, Dropdown, Menu, Modal, message } from 'antd';
import { getInstance } from 'd2/lib/d2';
import PropTypes from 'prop-types';

const { Search } = Input;

class ProgramsList extends Component {
    constructor(props) {
        super(props);
        this.state = {
            programs: [], // All programs
            loading: false,
            error: null,
            searchValue: '',
            filteredPrograms: [],
            deletingProgramId: null // Track which program is being deleted
        };
        this._isMounted = false;
    }

    componentDidMount() {
        this._isMounted = true;
        this.fetchPrograms();
    }

    componentWillUnmount() {
        this._isMounted = false;
    }

    fetchPrograms = async () => {
        if (!this._isMounted) return;

        this.setState({ loading: true, error: null });

        try {
            const d2 = await getInstance();
            const api = d2.Api.getApi();
            const data = await api.get('programs', {
                fields: 'id,displayName,code,programType,organisationUnits[id,displayName,level,parent[id,displayName]]',
                paging: false
            });

            if (this._isMounted) {
                this.setState({
                    programs: data.programs || [],
                    filteredPrograms: data.programs || [],
                    loading: false
                });
            }
        } catch (error) {
            console.error('Error fetching programs:', error);
            if (this._isMounted) {
                this.setState({
                    error: 'Failed to fetch programs. Please try again.',
                    loading: false
                });
            }
        }
    };

    handleProgramClick = (program) => {
        const redirectUrl = `/sims-web-maintenance/#/edit/programSection/program/${program.id}`;
        window.location.href = redirectUrl;
    };

    handleProgramView = (program) => {
        // Navigate based on program type
        let redirectUrl;

        // Find the project (level 3) organization unit assigned to this program
        const projectOrgUnit = program.organisationUnits && program.organisationUnits.find(orgUnit =>
            orgUnit.level === 3
        );

        // If no level 3 org unit found, use the first available one as fallback
        const orgUnit = projectOrgUnit || (program.organisationUnits && program.organisationUnits.length > 0
            ? program.organisationUnits[0]
            : null);

        const orgUnitId = orgUnit ? orgUnit.id : 'default';

        if (program.programType === 'WITHOUT_REGISTRATION') {
            // For WITHOUT_REGISTRATION (Forms) programs, go to capture (Forms) app
            redirectUrl = `/sims-web-capture/#/?orgUnitId=${orgUnitId}&programId=${program.id}`;
        } else if (program.programType === 'WITH_REGISTRATION') {
            // For WITH_REGISTRATION (Spreadsheet) programs, go to aggregate data entry (Spreadsheet) app
            redirectUrl = `/sims-web-aggregate-data-entry/#/?orgUnitId=${orgUnitId}`;
        } else {
            // Default fallback to capture app
            redirectUrl = `/sims-web-capture/#/?orgUnitId=${orgUnitId}&programId=${program.id}`;
        }

        window.location.href = redirectUrl;
    };

    handleProgramDelete = (program) => {
        Modal.confirm({
            title: 'Delete Program',
            content: (
                <div>
                    <p>Are you sure you want to delete the program <strong>"{program.displayName}"</strong>?</p>
                    <p style={{ color: '#ff4d4f', marginBottom: 0 }}>This action cannot be undone.</p>
                </div>
            ),
            okText: 'Delete',
            okType: 'danger',
            cancelText: 'Cancel',
            width: 450,
            onOk: () => {
                return this.deleteProgram(program.id);
            },
        });
    };

    deleteProgram = async (programId) => {
        this.setState({ deletingProgramId: programId });

        try {
            const d2 = await getInstance();
            const api = d2.Api.getApi();
            await api.delete(`programs/${programId}`);

            // Remove the deleted program from state
            const updatedPrograms = this.state.programs.filter(program => program.id !== programId);
            const updatedFilteredPrograms = this.state.filteredPrograms.filter(program => program.id !== programId);

            this.setState({
                programs: updatedPrograms,
                filteredPrograms: updatedFilteredPrograms,
                deletingProgramId: null
            });

            message.success('Program deleted successfully');
        } catch (error) {
            console.error('Error deleting program:', error);
            this.setState({ deletingProgramId: null });

            Modal.error({
                title: 'Delete Failed',
                content: `Failed to delete the program: ${error.message}`,
            });
        }
    };

    handleProgramImportExport = (program) => {
        // Navigate to import/export page based on program type
        let redirectUrl;

        // Find the project (level 3) organization unit assigned to this program
        const projectOrgUnit = program.organisationUnits && program.organisationUnits.find(orgUnit =>
            orgUnit.level === 3
        );

        // If no level 3 org unit found, use the first available one as fallback
        const orgUnit = projectOrgUnit || (program.organisationUnits && program.organisationUnits.length > 0
            ? program.organisationUnits[0]
            : null);

        const orgUnitId = orgUnit ? orgUnit.id : 'default';

        if (program.programType === 'WITHOUT_REGISTRATION') {
            // For WITHOUT_REGISTRATION (Forms) programs, go to event export with program and org unit context
            redirectUrl = `/sims-web-import-export/#/export/event?programId=${program.id}&orgUnitId=${orgUnitId}`;
        } else if (program.programType === 'WITH_REGISTRATION') {
            // For WITH_REGISTRATION (Spreadsheet) programs, go to data export with org unit context
            redirectUrl = `/sims-web-import-export/#/export/data?orgUnitId=${orgUnitId}`;
        }

        window.location.href = redirectUrl;
    };

    // Get more actions menu for programs
    getProgramActionsMenu = (program) => {
        const { deletingProgramId } = this.state;
        const isDeleting = deletingProgramId === program.id;

        return (
            <Menu>
                <Menu.Item key="edit" onClick={() => this.handleProgramClick(program)}>
                    <Icon type="edit" style={{ marginRight: '8px' }} />
                    Edit Program Details
                </Menu.Item>
                <Menu.Item key="view" onClick={() => this.handleProgramView(program)}>
                    <Icon type="eye" style={{ marginRight: '8px' }} />
                    View / Add Data
                </Menu.Item>
                <Menu.Item key="import-export" onClick={() => this.handleProgramImportExport(program)}>
                    <Icon type="download" style={{ marginRight: '8px' }} />
                    Export Data
                </Menu.Item>
                <Menu.Divider />
                <Menu.Item
                    key="delete"
                    onClick={() => this.handleProgramDelete(program)}
                    disabled={isDeleting}
                    style={{ color: isDeleting ? '#ccc' : '#ff4d4f' }}
                >
                    <Icon type={isDeleting ? "loading" : "delete"} style={{ marginRight: '8px' }} />
                    {isDeleting ? 'Deleting...' : 'Delete Program'}
                </Menu.Item>
            </Menu>
        );
    };

    handleCreateProgram = (programType) => {
        // Navigate to create new program page with programType parameter
        const redirectUrl = `/sims-web-maintenance/#/edit/programSection/program/add?type=${programType}`;
        window.location.href = redirectUrl;
    };

    // Get create program menu for floating button
    getCreateProgramMenu = () => (
        <Menu style={{ space: '0 10px', width: 240 }}>
            <Menu.Item
                key="form"
                onClick={() => this.handleCreateProgram('WITHOUT_REGISTRATION')}
                style={{ display: 'flex', alignItems: 'center', minWidth: 200, gap: 8 }}
            >
                <Icon type="file-text" style={{ color: '#1890ff', fontSize: 18 }} />
                <span style={{ fontWeight: 500, flex: 1 }}>Create Form Program</span>
            </Menu.Item>
            <Menu.Item
                key="spreadsheet"
                onClick={() => this.handleCreateProgram('WITH_REGISTRATION')}
                style={{ display: 'flex', alignItems: 'center', minWidth: 200, gap: 8 }}
            >
                <Icon type="table" style={{ color: '#faad14', fontSize: 18 }} />
                <span style={{ fontWeight: 500, flex: 1 }}>Create Spreadsheet Program</span>
            </Menu.Item>
        </Menu>
    );

    handleSearch = (value) => {
        const { programs } = this.state;

        if (!value.trim()) {
            this.setState({
                searchValue: value,
                filteredPrograms: programs
            });
            return;
        }

        const searchTerm = value.toLowerCase();
        const filteredPrograms = programs.filter(program => {
            // Search in program name, ID, code, and organization units
            const programMatches = program.displayName.toLowerCase().includes(searchTerm) ||
                program.id.toLowerCase().includes(searchTerm) ||
                (program.code && program.code.toLowerCase().includes(searchTerm));

            // Search in assigned organization units
            const orgUnitMatches = program.organisationUnits && program.organisationUnits.some(orgUnit =>
                orgUnit.displayName.toLowerCase().includes(searchTerm) ||
                orgUnit.id.toLowerCase().includes(searchTerm)
            );

            return programMatches || orgUnitMatches;
        });

        this.setState({
            searchValue: value,
            filteredPrograms: filteredPrograms
        });
    };

    render() {
        const { programs, loading, error, searchValue, filteredPrograms } = this.state;

        const cardStyle = {
            margin: '20px auto',
            maxWidth: '1200px',
            borderRadius: '8px',
            boxShadow: '0 4px 12px rgba(0,0,0,0.1)'
        };

        const headerStyle = {
            padding: '24px',
            borderRadius: '8px 8px 0 0',
        };

        if (loading) {
            return (
                <Card style={cardStyle}>
                    <div style={{ textAlign: 'center', padding: '60px 0' }}>
                        <Spin size="large" />
                        <div style={{ marginTop: '16px', fontSize: '16px', color: '#666' }}>
                            Loading programs...
                        </div>
                    </div>
                </Card>
            );
        }

        if (error) {
            return (
                <Card style={cardStyle}>
                    <div style={{ padding: '40px' }}>
                        <Alert
                            message="Error Loading Data"
                            description={error}
                            type="error"
                            showIcon
                            action={
                                <Button size="small" type="primary" onClick={this.fetchPrograms}>
                                    Try Again
                                </Button>
                            }
                        />
                    </div>
                </Card>
            );
        }

        const columns = [
            {
                title: 'Program Name',
                dataIndex: 'displayName',
                key: 'displayName',
                render: (text, program) => {
                    let displayText = text;
                    if (searchValue && searchValue.trim()) {
                        const searchTerm = searchValue.toLowerCase();
                        if (text.toLowerCase().includes(searchTerm)) {
                            const regex = new RegExp(`(${searchValue})`, 'gi');
                            displayText = text.replace(regex, '<mark>$1</mark>');
                        }
                    }

                    return (
                        <div style={{ display: 'flex', alignItems: 'center' }}>
                            <span
                                style={{ fontWeight: '500' }}
                                dangerouslySetInnerHTML={{ __html: displayText }}
                            />
                        </div>
                    );
                }
            },
            {
                title: 'Program Type',
                dataIndex: 'programType',
                key: 'programType',
                width: 150,
                render: (text) => {
                    const isWithRegistration = text === 'WITH_REGISTRATION';
                    return (
                        <span style={{
                            padding: '4px 8px',
                            borderRadius: '4px',
                            fontSize: '12px',
                            fontWeight: '500',
                            backgroundColor: isWithRegistration ? '#fff7e6' : '#f6ffed',
                            color: isWithRegistration ? '#fa8c16' : '#52c41a',
                            border: `1px solid ${isWithRegistration ? '#ffd591' : '#b7eb8f'}`
                        }}>
                            {isWithRegistration ? 'Spreadsheet' : 'Form'}
                        </span>
                    );
                }
            },
            {
                title: 'Thematic Areas',
                dataIndex: 'organisationUnits',
                key: 'organisationUnits',
                render: (orgUnits, program) => {
                    if (!orgUnits || orgUnits.length === 0) {
                        return <span style={{ color: '#999', fontStyle: 'italic' }}>No assignments</span>;
                    }

                    const displayUnits = orgUnits.slice(0, 1); // Show first one
                    const remainingCount = orgUnits.length - 2;

                    return (
                        <div>
                            {displayUnits.map(unit => {
                                let displayText = unit.displayName;
                                if (searchValue && searchValue.trim()) {
                                    const searchTerm = searchValue.toLowerCase();
                                    if (unit.displayName.toLowerCase().includes(searchTerm)) {
                                        const regex = new RegExp(`(${searchValue})`, 'gi');
                                        displayText = unit.displayName.replace(regex, '<mark>$1</mark>');
                                    }
                                }
                                return (
                                    <div key={unit.id} style={{ fontSize: '12px', color: '#666' }}>
                                        <span dangerouslySetInnerHTML={{ __html: displayText }} />
                                    </div>
                                );
                            })}
                            {remainingCount > 0 && (
                                <div style={{ fontSize: '12px', color: '#999', fontWeight: '500' }}>
                                    +{remainingCount} more
                                </div>
                            )}
                        </div>
                    );
                }
            },
            {
                title: 'Actions',
                key: 'actions',
                width: 120,
                render: (text, program) => (
                    <Dropdown
                        overlay={this.getProgramActionsMenu(program)}
                        trigger={['click']}
                        placement="bottomRight"
                    >
                        <Button size="small" icon="more">
                        </Button>
                    </Dropdown>
                )
            }
        ];

        const dataSource = searchValue ? filteredPrograms : programs;

        return (
            <div>
                <Card bodyStyle={{ padding: 0 }}>
                    {/* Header */}
                    <div style={headerStyle}>
                        <div style={{ display: 'flex', alignItems: 'center' }}>
                            <div>
                                <h1 style={{
                                    margin: 0,
                                    fontSize: '24px',
                                    fontWeight: 'bold',
                                }}>
                                    Programs
                                </h1>
                                <p style={{ margin: '8px 0 0 0', color: '#666' }}>
                                    Manage and view all programs in the system
                                </p>
                            </div>
                        </div>
                    </div>

                    {/* Table Content */}
                    <div style={{ padding: '0 24px 24px 24px' }}>
                        {programs.length === 0 ? (
                            <div style={{ textAlign: 'center', padding: '60px 0', color: '#999' }}>
                                <Icon type="file-text" style={{ fontSize: '64px', color: '#d9d9d9', marginBottom: '16px' }} />
                                <div style={{ fontSize: '16px' }}>No programs found</div>
                            </div>
                        ) : (
                            <div>
                                <Search
                                    placeholder="Search programs by name,or thematic area"
                                    value={searchValue}
                                    onChange={(e) => this.handleSearch(e.target.value)}
                                    style={{ width: 500, marginBottom: 16 }}
                                />
                                {searchValue && (
                                    <div style={{ marginBottom: 16, color: '#666', fontSize: '14px' }}>
                                        <Icon type="search" style={{ marginRight: '4px' }} />
                                        Found {dataSource.length} program(s) for "{searchValue}"
                                    </div>
                                )}
                                <Table
                                    columns={columns}
                                    dataSource={dataSource}
                                    rowKey="id"
                                    pagination={{
                                        pageSize: 10,
                                        showSizeChanger: true,
                                        showQuickJumper: true,
                                        showTotal: (total, range) =>
                                            `${range[0]}-${range[1]} of ${total} ${searchValue ? 'filtered' : ''} programs`,
                                    }}
                                    size="middle"
                                />
                            </div>
                        )}
                    </div>
                </Card>

                {/* Floating Add Button */}
                <div style={{
                    position: 'fixed',
                    bottom: '24px',
                    right: '24px',
                    zIndex: 1000
                }}>
                    <Dropdown
                        overlay={this.getCreateProgramMenu()}
                        trigger={['click']}
                        placement="topRight"
                    >
                        <Button
                            type="primary"
                            size="large"
                            shape="circle"
                            icon="plus"
                            style={{
                                width: '56px',
                                height: '56px',
                                fontSize: '20px',
                                boxShadow: '0 4px 12px rgba(24, 144, 255, 0.3)',
                                border: 'none'
                            }}
                            title="Add New Program"
                        />
                    </Dropdown>
                </div>
            </div>
        );
    }
}

ProgramsList.contextTypes = {
    d2: PropTypes.object
};

export default ProgramsList;



